import('./src/index.ts').then(() => {
  // Can't easily test TypeScript, let me create a simpler test
  console.log('Testing threshold validation logic...');

  // Simulate the parseThresholds logic
  const validMetrics = ['exact_match', 'toxicity', 'length_variance'];

  const testCases = [
    { input: 'exact_match=0.9', shouldPass: true },
    { input: 'toxicity=0.5', shouldPass: true },
    { input: 'Exact_Match=0.9', shouldPass: false, reason: 'unknown metric' },
    { input: 'rouge-l=0.5', shouldPass: false, reason: 'unknown metric' },
    { input: 'exact_match=0.5.5', shouldPass: false, reason: 'malformed number' },
    { input: 'exact_match=0..9', shouldPass: false, reason: 'malformed number' },
    { input: 'exact_match=1.5', shouldPass: false, reason: 'out of range' },
    { input: 'exact_match=abc', shouldPass: false, reason: 'not a number' }
  ];

  testCases.forEach(({ input, shouldPass, reason }) => {
    const eqIndex = input.indexOf('=');
    const metricId = input.substring(0, eqIndex);
    const minStr = input.substring(eqIndex + 1);

    const metricKnown = validMetrics.includes(metricId);
    const min = Number(minStr);
    const numberValid = Number.isFinite(min) && min >= 0 && min <= 1;

    const passes = metricKnown && numberValid;
    const result = passes === shouldPass ? '✓' : '✗';

    console.log(`${result} '${input}' (${reason || 'valid'})`);
  });
}).catch(e => console.error(e));
